export function resolveDoc(id: string): DocTemplate | undefined {
  const leaf = leafById(id);
  const detailed = docById(id);
  if (detailed) {
    const m = metaFor(id);
    return {
      ...detailed,
      rationale: rationaleFor(id),
      difficulty: m?.difficulty,
      importance: m?.importance,
      effort: effortFor(id),
      prepDocs: prepDocsFor(id),
